def validar_comentario(comentario):
    '''Valida que un comentario no contenga código malicioso'''
    # Whitelist: solo caracteres seguros
    if not re.match(r'^[\w\s.,!?¿¡áéíóúÁÉÍÓÚñÑ-]+$', comentario):
        return {'valido': False, 'error': 'Caracteres no permitidos'}

    if len(comentario) > 1000:
        return {'valido': False, 'error': 'Comentario demasiado largo'}

    # Detectar patrones sospechosos
    patrones_sospechosos = [
        r'<script', r'javascript:', r'on\w+=', r'data:', r'eval\('
    ]
    for patron in patrones_sospechosos:
        if re.search(patron, comentario, re.IGNORECASE):
            return {'valido': False, 'error': f'Patrón sospechoso: {patron}'}

    return {'valido': True, 'comentario': comentario}

# Test con comentarios maliciosos
comentarios_maliciosos = [
    "Hola <script>alert('xss')</script>",
    "Visita javascript:alert('xss')",
    "<img src=x onerror=alert('xss')>",
]

print('--- Validación de comentarios ---')
for comentario in comentarios_maliciosos:
    resultado = validar_comentario(comentario)
    print(f'Comentario: {comentario[:50]}...')
    print(f'Resultado:  {resultado}')
    print()

